-- ============================================================================
-- Сид каталога (ADR-0004): catalog.product_types + catalog.country_codes
-- из текущих public.products (ТН ВЭД-10) и public.services (ОКЭД/ИКПУ), плюс
-- колонка-мост product_type_id на products/services.
-- Сгенерировано scripts/generate_catalog_seed.mjs — правки вносить там.
-- Товаров: 261, HS6-типов: 26; услуг: 2, типов услуг: 2
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Мост: product_type_id на public.products / public.services
-- ----------------------------------------------------------------------------
alter table public.products add column product_type_id uuid references catalog.product_types(id);
create index products_product_type_id_idx on public.products (product_type_id);
alter table public.services add column product_type_id uuid references catalog.product_types(id);
create index services_product_type_id_idx on public.services (product_type_id);

-- ----------------------------------------------------------------------------
-- catalog.product_types — товары (HS6)
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- catalog.product_types — услуги (UNSPSC)
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- catalog.country_codes — UZ: tnved (товары, полный код) + oked/ikpu (услуги)
-- ----------------------------------------------------------------------------

-- ----------------------------------------------------------------------------
-- Обратная связка: product_type_id на products/services по совпадению кода
-- (через только что заполненный catalog.country_codes — он и есть указатель
-- нацкода на тип, ADR-0004)
-- ----------------------------------------------------------------------------
update public.products p set product_type_id = cc.product_type_id
from catalog.country_codes cc
where cc.country = 'UZ' and cc.system = 'tnved' and cc.code = p.hs_code;
update public.services s set product_type_id = cc.product_type_id
from catalog.country_codes cc
where cc.country = 'UZ' and cc.system = 'oked' and cc.code = s.oked_code;
